1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.clube.NiveisClubeRegistry;
5	import com.loja.checkout.cupom.Cupom;
6	import com.loja.checkout.cupom.CupomRegistry;
7	import com.loja.checkout.dto.CheckoutRequest;
8	import com.loja.checkout.dto.CheckoutResponse;
9	import com.loja.checkout.dto.ItemRequest;
10	import com.loja.checkout.entrega.EntregaRegistry;
11	import com.loja.checkout.entrega.ModalidadeEntrega;
12	import com.loja.checkout.exception.CheckoutException;
13	import com.loja.checkout.pagamento.FormaPagamento;
14	import com.loja.checkout.pagamento.PagamentoRegistry;
15	import com.loja.checkout.pagamento.ResultadoPagamento;
16	import com.loja.checkout.regiao.Regiao;
17	import org.springframework.stereotype.Service;
18	
19	import java.math.BigDecimal;
20	import java.math.RoundingMode;
21	import java.util.List;
22	
23	@Service
24	public class CheckoutService {
25	
26	    private final EntregaRegistry entregas;
27	    private final CupomRegistry cupons;
28	    private final PagamentoRegistry pagamentos;
29	    private final NiveisClubeRegistry niveisClube;
30	
31	    public CheckoutService(EntregaRegistry entregas, CupomRegistry cupons,
32	                           PagamentoRegistry pagamentos, NiveisClubeRegistry niveisClube) {
33	        this.entregas = entregas;
34	        this.cupons = cupons;
35	        this.pagamentos = pagamentos;
36	        this.niveisClube = niveisClube;
37	    }
38	
39	    public CheckoutResponse calcular(CheckoutRequest request) {
40	        validarItens(request.itens());
41	
42	        NivelClube nivel = niveisClube.buscar(request.nivelClube());
43	        if (nivel == null) throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
44	
45	        Regiao regiao = Regiao.porNome(request.regiao());
46	        if (regiao == null) throw new CheckoutException("REGIAO_INVALIDA");
47	
48	        ModalidadeEntrega modalidade = entregas.buscar(request.modalidadeEntrega());
49	        if (modalidade == null) throw new CheckoutException("MODALIDADE_INVALIDA");
50	
51	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
52	        if (!modalidade.disponivel(pesoTotal)) throw new CheckoutException("MODALIDADE_INDISPONIVEL");
53	
54	        Cupom cupom = null;
55	        if (request.cupom() != null && !request.cupom().isEmpty()) {
56	            cupom = cupons.buscar(request.cupom());
57	            if (cupom == null) throw new CheckoutException("CUPOM_INVALIDO");
58	        }
59	
60	        BigDecimal subtotal = calcularSubtotal(request.itens());
61	
62	        if (cupom != null && !cupom.aplicavel(subtotal, request.itens())) {
63	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
64	        }
65	
66	        FormaPagamento formaPgto = pagamentos.buscar(request.formaPagamento());
67	        if (formaPgto == null) throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
68	
69	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
70	        if (!formaPgto.parcelasValidas(parcelas)) throw new CheckoutException("PARCELAMENTO_INVALIDO");
71	
72	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
73	        if (nivel.freteGratis()) {
74	            frete = BigDecimal.ZERO.setScale(2);
75	        }
76	
77	        BigDecimal descontoCupom = cupom != null
78	                ? cupom.calcularDesconto(subtotal, request.itens(), frete)
79	                : BigDecimal.ZERO.setScale(2);
80	
81	        BigDecimal seguro = subtotal.multiply(regiao.taxaSeguro()).setScale(2, RoundingMode.HALF_EVEN);
82	
83	        BigDecimal totalPedido = subtotal
84	                .subtract(descontoCupom)
85	                .add(frete)
86	                .add(seguro);
87	
88	        if (!formaPgto.disponivel(totalPedido)) throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
89	
90	        ResultadoPagamento resultado = formaPgto.calcular(totalPedido, parcelas);
91	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido);
92	
93	        BigDecimal credito = nivel.calcularCredito(subtotal);
94	        boolean brinde = nivel.temBrinde(subtotal);
95	
96	        return new CheckoutResponse(
97	                subtotal,
98	                descontoCupom,
99	                frete,
100	                modalidade.prazoDias(),
101	                seguro,
102	                ajuste,
103	                resultado.totalFinal(),
104	                resultado.parcelas(),
105	                resultado.valorParcela(),
106	                credito,
107	                brinde
108	        );
109	    }
110	
111	    private void validarItens(List<ItemRequest> itens) {
112	        if (itens == null || itens.isEmpty()) throw new CheckoutException("PEDIDO_INVALIDO");
113	        for (ItemRequest item : itens) {
114	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
115	                    || item.quantidade() == null || item.quantidade() <= 0
116	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
117	                throw new CheckoutException("PEDIDO_INVALIDO");
118	            }
119	        }
120	    }
121	
122	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
123	        BigDecimal subtotal = BigDecimal.ZERO;
124	        for (ItemRequest item : itens) {
125	            subtotal = subtotal.add(
126	                    item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
127	        }
128	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
129	    }
130	
131	    private BigDecimal calcularPesoTotal(List<ItemRequest> itens) {
132	        BigDecimal peso = BigDecimal.ZERO;
133	        for (ItemRequest item : itens) {
134	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
135	        }
136	        return peso;
137	    }
138	}
