1	package com.loja.checkout.pagamento;
2	
3	import org.springframework.stereotype.Component;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	@Component
10	public class PagamentoCartao implements FormaPagamento {
11	
12	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
13	    private static final int PARCELAS_SEM_JUROS = 3;
14	    private static final MathContext MC = MathContext.DECIMAL128;
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean parcelasValidas(int parcelas) {
23	        return parcelas >= 1 && parcelas <= 12;
24	    }
25	
26	    @Override
27	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
28	        if (parcelas <= PARCELAS_SEM_JUROS) {
29	            BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
30	            BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
31	            return new ResultadoPagamento(totalFinal, parcelas, valorParcela);
32	        }
33	
34	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_MENSAL);
35	        BigDecimal potencia = umMaisTaxa.pow(parcelas, MC);
36	        BigDecimal potenciaNeg = BigDecimal.ONE.divide(potencia, MC);
37	        BigDecimal denominador = BigDecimal.ONE.subtract(potenciaNeg, MC);
38	        BigDecimal valorParcela = totalPedido.multiply(TAXA_MENSAL, MC)
39	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
40	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
41	        return new ResultadoPagamento(totalFinal, parcelas, valorParcela);
42	    }
43	}
